<?php
declare(strict_types=1);require_once __DIR__.'/../config/agency_auth.php';agency_session();if(agency_user()){header('Location: /nexustraveltech/acente/');exit;}$error='';if($_SERVER['REQUEST_METHOD']==='POST'){$email=filter_input(INPUT_POST,'email',FILTER_VALIDATE_EMAIL);$password=$_POST['password']??'';$q=db()->prepare("SELECT u.id,u.agency_id,u.full_name,u.email,u.password_hash,u.role,a.company_name FROM agency_users u JOIN agencies a ON a.id=u.agency_id WHERE u.email=? AND a.status='active' LIMIT 1");$q->execute([$email]);$u=$q->fetch();if($u&&password_verify($password,$u['password_hash'])){unset($u['password_hash']);$_SESSION['agency_user']=$u;db()->prepare('UPDATE agency_users SET last_login_at=now() WHERE id=?')->execute([$u['id']]);header('Location: /nexustraveltech/acente/');exit;}$error='E-posta, şifre veya acente durumu hatalı.';}?><!doctype html><html lang="tr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>NEXUS Acenta</title><style>body{min-height:100vh;margin:0;display:grid;place-items:center;font-family:Arial;background:#10211f}.c{background:#fff;width:min(400px,calc(100% - 30px));padding:30px}.c input,.c button{width:100%;box-sizing:border-box;padding:12px;margin:7px 0}.c button{background:#d7ff48;border:0;font-weight:bold}.e{color:#c33}</style></head><body><form method="post" class="c"><h1>NEXUS Acenta</h1><p>Canlı ürün, teklif ve rezervasyon merkezi.</p><?php if($error):?><p class="e"><?=htmlspecialchars($error)?></p><?php endif;?><input type="email" name="email" placeholder="İş e-postası" required><input type="password" name="password" placeholder="Şifre" required><button>Giriş yap</button></form></body></html>
